document.addEventListener("DOMContentLoaded",init);const RELATED_LIMIT=12;let storeContact={phone:"",whatsapp:"",messenger:""};let product=null;let slug=null;async function init(){slug=getQueryParam("store");const productId=getQueryParam("product");const statusEl=document.getElementById("product-status");if(!slug||!productId){statusEl.textContent="Product not found.";return}localStorage.setItem("skiri_active_store",slug);const backLink=document.getElementById("back-to-store-link");const viewStore=document.getElementById("view-store-link");const storeHref=`store.html?store=${encodeURIComponent(slug)}`;backLink.href=storeHref;viewStore.href=storeHref;const stop=startLoadingMessage(statusEl);const request=Api.get("listProducts",{storeSlug:slug});window.__criticalReady=request;window.__storeInfoPromise=request.then(r=>r&&r.ok?{storeName:r.storeName,logoUrl:r.storeLogoUrl}:null);const res=await request;stop();if(!res.ok){showLoadFailedMessage(statusEl);return}product=(res.products||[]).find(p=>p.productId===productId);if(!product){statusEl.textContent="Sorry, this product is no longer available.";return}statusEl.textContent="";window.__storeOpen=res.storeOpen!==false;storeContact={phone:res.storePhone||"",whatsapp:res.storeWhatsapp||"",messenger:res.storeMessenger||""};document.getElementById("store-name-tagline").textContent=res.storeName||"Store";if(res.storeLogoUrl){const img=document.getElementById("store-logo-img");img.src=optimizedImageUrl(res.storeLogoUrl,IMG_W.logo);img.alt=res.storeName;img.classList.remove("hidden")}if(res.storePhone){const ph=document.getElementById("store-phone-line");ph.textContent=res.storePhone;ph.classList.remove("hidden")}document.getElementById("store-delivery-icons").innerHTML=renderDeliveryIcons({truck:res.storeDeliveryTruck,ship:res.storeDeliveryShip,airCargo:res.storeDeliveryAirCargo,pickPay:res.storeDeliveryPickPay,truckCost:res.storeDeliveryTruckCost,shipCost:res.storeDeliveryShipCost,airCargoCost:res.storeDeliveryAirCargoCost});renderShippingNote("product-shipping-note",res);document.getElementById("product-detail").innerHTML=renderProductCard(product);document.title=`${product.name} — Mwakete`;wireActions();wireGallery();if(!window.__storeOpen){document.querySelectorAll("#product-detail .add-to-cart-btn, #product-detail .request-booking-btn").forEach(btn=>{btn.disabled=true;btn.title="This store is closed right now"});const detail=document.getElementById("product-detail");const note=document.createElement("p");note.className="store-closed-note";note.innerHTML='<span class="store-closed-pill">Closed</span> This store is not taking orders right now. You can still chat with them.';detail.insertBefore(note,detail.firstChild)}loadReviews(product.productId);showRelatedSkeleton();whenIdle(loadRelated)}function showRelatedSkeleton(){const section=document.getElementById("related-section");const list=document.getElementById("related-list");if(!section||!list)return;list.innerHTML=Array.from({length:3},()=>'<div class="related-card related-card--skeleton" aria-hidden="true">'+'<div class="related-skeleton-image"></div>'+'<div class="related-skeleton-line"></div>'+'<div class="related-skeleton-line"></div>'+"</div>").join("");section.hidden=false}async function loadRelated(){if(!product)return;const section=document.getElementById("related-section");const list=document.getElementById("related-list");if(!section||!list)return;let res;try{res=await Api.get("searchProducts",{q:"",category:categoryIdOf(product.category),type:listingTypeOf(product)||""})}catch(e){section.hidden=true;list.innerHTML="";return}if(!res||!res.ok){section.hidden=true;list.innerHTML="";return}const items=(res.products||[]).filter(p=>p.productId!==product.productId).slice(0,RELATED_LIMIT);if(!items.length){section.hidden=true;list.innerHTML="";return}list.innerHTML=items.map(p=>renderBrowseProductCard(p,{cardClass:"related-card",showLocation:true})).join("");section.hidden=false}function wireActions(){const addBtn=document.querySelector("#product-detail .add-to-cart-btn");if(addBtn)addBtn.addEventListener("click",()=>onAddToCart(addBtn));const bookBtn=document.querySelector("#product-detail .request-booking-btn");if(bookBtn)bookBtn.addEventListener("click",()=>onRequestBooking(bookBtn))}function wireGallery(){document.querySelectorAll("#product-detail .product-gallery-thumb").forEach(thumb=>{thumb.addEventListener("click",()=>{const track=document.querySelector("#product-detail .product-gallery-track");if(!track)return;const index=Number(thumb.dataset.index)||0;track.scrollTo({left:index*track.clientWidth,behavior:"smooth"})})})}function onAddToCart(btn){const select=document.getElementById(`variety-${product.productId}`);const qtyInput=document.getElementById(`qty-${product.productId}`);const variant=product.variants.find(v=>v.variantId===select.value);if(!variant)return;const qty=Math.max(1,parseInt(qtyInput.value,10)||1);Cart.addItem(slug,{variantId:variant.variantId,productId:product.productId,label:`${product.name} — ${variant.label}`,unitPrice:variant.price,qty:qty});showAddingToCartState(btn);if(typeof updateBottomNavCartBadge==="function")updateBottomNavCartBadge()}function showAddingToCartState(btn){btn.disabled=true;btn.classList.add("btn-adding");btn.innerHTML='Adding<span class="btn-saving-dots"><span></span><span></span><span></span></span>';setTimeout(()=>{btn.disabled=false;btn.classList.remove("btn-adding");btn.textContent="Add to Cart"},900)}async function onRequestBooking(btn){const pid=product.productId;const statusEl=document.getElementById(`booking-status-${pid}`);const select=document.getElementById(`variety-${pid}`);const startInput=document.getElementById(`start-${pid}`);const endInput=document.getElementById(`end-${pid}`);const nameInput=document.getElementById(`name-${pid}`);const phoneInput=document.getElementById(`phone-${pid}`);const notesInput=document.getElementById(`notes-${pid}`);const customerName=nameInput.value.trim();const customerPhone=phoneInput.value.trim();if(!customerName||!customerPhone){setFormStatus(statusEl,"Please enter your name and phone number.","error");return}if(!startInput.value||!endInput.value){setFormStatus(statusEl,"Please choose a pick-up and return date.","error");return}if(startInput.value>=endInput.value){setFormStatus(statusEl,"Return date must be after pick-up date.","error");return}btn.disabled=true;btn.innerHTML='Sending<span class="btn-saving-dots"><span></span><span></span><span></span></span>';setFormStatus(statusEl,"");const res=await Api.post("createBookingRequest",{storeSlug:slug,productId:pid,variantId:select.value,startDate:startInput.value,endDate:endInput.value,customerName:customerName,customerPhone:customerPhone,notes:notesInput.value.trim()});if(!res.ok){setFormStatus(statusEl,res.error||"Could not send this booking request.","error");btn.disabled=false;btn.textContent="Request Booking";return}btn.textContent="Requested";setFormStatus(statusEl,"Booking request sent — the vendor will confirm or decline.","success");const contactEl=document.getElementById(`booking-contact-${pid}`);if(contactEl){contactEl.innerHTML=sellerContactButtons({phone:storeContact.phone,whatsapp:storeContact.whatsapp,messenger:storeContact.messenger});contactEl.classList.remove("hidden");wireContactUnavailable()}}async function loadReviews(productId){const section=document.getElementById("reviews-section");const statusEl=document.getElementById("reviews-status");section.hidden=false;const stop=startLoadingMessage(statusEl);const res=await Api.get("listProductReviews",{productId:productId});stop();if(!res.ok){showLoadFailedMessage(statusEl);return}statusEl.textContent="";renderReviewSummary(res);renderReviewList(res.reviews||[]);renderReviewForm(productId,res.reviews||[])}function renderReviewToggleScore(data){const el=document.getElementById("reviews-toggle-score");if(!el)return;const count=Number(data.count)||0;if(count===0){el.textContent="No reviews yet";return}const avg=Number(data.average);el.textContent=`★ ${avg.toFixed(1)} · ${count} review${count===1?"":"s"}`}function renderReviewSummary(data){renderReviewToggleScore(data);const el=document.getElementById("reviews-summary");const count=Number(data.count)||0;if(count===0){el.innerHTML='<p class="helper-text">Be the first to review this product.</p>';return}const avg=Number(data.average);const dist=data.distribution||[0,0,0,0,0];const rows=[5,4,3,2,1].map(star=>{const n=Number(dist[star-1])||0;const pct=count?Math.round(n/count*100):0;return`<div class="rating-bar-row">\n          <span class="rating-bar-label"><span class="rating-bar-star-num">${star}</span><span class="rating-bar-star">★</span></span>\n          <span class="rating-bar"><span class="rating-bar-fill" style="width:${pct}%"></span></span>\n          <span class="rating-bar-count">${n}</span>\n        </div>`}).join("");el.innerHTML=`\n    <div class="reviews-average">\n      <strong class="reviews-average-value">${avg.toFixed(1)}</strong>\n      ${renderStars(avg,count)}\n      <span class="helper-text">${count} review${count===1?"":"s"}</span>\n    </div>\n    <div class="rating-bars">${rows}</div>`}function renderReviewList(reviews){const el=document.getElementById("reviews-list");el.innerHTML=reviews.map(r=>`\n      <article class="review-item">\n        <div class="review-head">\n          ${renderStars(r.rating,1).replace(/<span class="rating-count">.*?<\/span>/,"")}\n          <span class="review-author">${escapeHtml(r.customerName||"Customer")}</span>\n          ${r.verifiedPurchase?'<span class="review-verified">✓ Verified purchase</span>':""}\n        </div>\n        ${r.comment?`<p class="review-comment">${escapeHtml(r.comment)}</p>`:""}\n        <p class="review-date helper-text">${escapeHtml(formatReviewDate(r.createdAt))}</p>\n      </article>`).join("")}function formatReviewDate(iso){const d=new Date(iso);return isNaN(d.getTime())?"":d.toLocaleDateString()}function renderReviewForm(productId,reviews){const slot=document.getElementById("review-form-slot");const signedIn=typeof CustomerAuth!=="undefined"&&CustomerAuth.getToken();if(!signedIn){slot.innerHTML='<p class="helper-text review-signin-prompt">'+'<a href="customer-login.html">Sign in or create an account</a> to leave a review.</p>';return}const profile=CustomerAuth.getProfile&&CustomerAuth.getProfile();const mine=profile&&reviews.some(r=>r.customerName===profile.name);if(mine){slot.innerHTML='<p class="helper-text">You have already reviewed this product.</p>';return}slot.innerHTML=`\n    <form class="review-form" id="review-form">\n      <fieldset class="review-stars-field">\n        <legend>Your rating</legend>\n        ${[1,2,3,4,5].map(n=>`<label class="review-star-choice">\n              <input type="radio" name="reviewRating" value="${n}" required>\n              <span>${n}★</span>\n            </label>`).join("")}\n      </fieldset>\n      <div class="field">\n        <label for="review-comment">Your review <span class="helper-text">(optional)</span></label>\n        <textarea id="review-comment" rows="3" maxlength="1000"></textarea>\n      </div>\n      <p class="form-error hidden" id="review-error"></p>\n      <button type="submit" class="btn btn-primary" id="review-submit">Submit review</button>\n    </form>`;document.getElementById("review-form").addEventListener("submit",e=>onSubmitReview(e,productId))}async function onSubmitReview(e,productId){e.preventDefault();const errorEl=document.getElementById("review-error");const btn=document.getElementById("review-submit");const checked=document.querySelector('input[name="reviewRating"]:checked');errorEl.classList.add("hidden");if(!checked){errorEl.textContent="Please choose a rating.";errorEl.classList.remove("hidden");return}btn.disabled=true;btn.innerHTML='Submitting<span class="btn-saving-dots"><span></span><span></span><span></span></span>';const res=await Api.post("submitReview",{token:CustomerAuth.getToken(),productId:productId,rating:Number(checked.value),comment:document.getElementById("review-comment").value.trim()});btn.disabled=false;btn.textContent="Submit review";if(!res.ok){errorEl.textContent=res.error||"Could not submit your review.";errorEl.classList.remove("hidden");return}await loadReviews(productId)}